use std::{collections::BTreeSet,env,fs,path::PathBuf};
fn inv(p:&str)->BTreeSet<String>{println!("cargo:rerun-if-changed={p}");fs::read_to_string(p).expect("read inventory").lines().map(str::trim).filter(|s|!s.is_empty()&&!s.starts_with('#')).map(|s|{assert!(s.chars().all(|c|c.is_ascii_alphanumeric()||c=='_'),"invalid export {s}");s.to_owned()}).collect()}
fn main(){println!("cargo:rerun-if-changed=src/lib.rs");println!("cargo:rerun-if-changed=exports/kernelbase-x64.def");let names=inv("exports/windows-11-x64-exports.txt");let def=fs::read_to_string("exports/kernelbase-x64.def").expect("missing .def");let mut declared=BTreeSet::new();for raw in def.lines(){let s=raw.trim();if s.is_empty()||s.starts_with(';')||s=="EXPORTS"||s.starts_with("LIBRARY "){continue}let n=s.split_whitespace().next().unwrap().split('=').next().unwrap();assert!(names.contains(n),"def export missing from inventory: {n}");declared.insert(n.to_owned());}assert_eq!(names,declared,".def and inventory mismatch");let mut out=String::from("// Generated placeholder exports.\n");for n in &names{if ["GetLastError","SetLastError","GetCurrentProcess","GetCurrentThread"].contains(&n.as_str()){continue}out.push_str(&format!("#[no_mangle]\npub extern \"system\" fn {n}() -> ULONG_PTR {{ 0 }}\n"));}let p=PathBuf::from(env::var_os("OUT_DIR").expect("OUT_DIR"));fs::write(p.join("kernelbase_exports.rs"),out).expect("write exports");println!("cargo:warning=kernelbase export list is a starter subset, not Windows 11 parity");}
